#!/usr/bin/env node
/**
 * ============================================================================
 * MAP COORDINATE CALIBRATION ALGORITHM
 * ============================================================================
 * 
 * This script documents and provides the exact coordinate system used by the
 * Tactical Map Guide app. Any agent or team member can use this logic to
 * determine calibration coordinates for any point on a map image, producing
 * values identical to those generated by the in-app calibration tool.
 *
 * USAGE:
 *   node scripts/map-coordinate-algorithm.js <mapId>
 *   node scripts/map-coordinate-algorithm.js --pixel <mapId> <pixelX> <pixelY>
 *   node scripts/map-coordinate-algorithm.js --percent <mapId> <rawX> <rawY>
 *   node scripts/map-coordinate-algorithm.js --all
 *
 * EXAMPLES:
 *   node scripts/map-coordinate-algorithm.js fate
 *   node scripts/map-coordinate-algorithm.js --pixel fate 655 424
 *   node scripts/map-coordinate-algorithm.js --percent fate 50 50
 *   node scripts/map-coordinate-algorithm.js --all
 * ============================================================================
 */

const fs = require('fs');
const path = require('path');

// ============================================================================
// STEP 1: MAP CONFIGURATION
// ============================================================================
// Each map has two critical properties:
//   - aspectRatio: width / height of the source image (from assetRegistry.ts)
//   - borderOffset: non-playable border margins in percentage units
//
// These values are defined per-map and MUST match the app's configuration.

function loadMapConfig(mapId) {
  const aspectRatios = {
    utopia:    0.71,
    blackheart: 1.008,
    colossus:  0.628,
    cortex:    0.604,
    odysseus:  1.491,
    fate:      0.647,
  };

  const dataPath = path.join(__dirname, '..', 'client', 'data', `${mapId}_data.json`);
  if (!fs.existsSync(dataPath)) {
    console.error(`Map data not found: ${dataPath}`);
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
  
  return {
    mapId,
    mapName: data.mapName,
    aspectRatio: aspectRatios[mapId] || 1,
    borderOffset: data.borderOffset || { top: 0, bottom: 0, left: 0, right: 0 },
    imageWidth: data.imageWidth || null,
    imageHeight: data.imageHeight || null,
    pointsOfInterest: data.pointsOfInterest || [],
    objectives: data.objectives || {},
  };
}


// ============================================================================
// STEP 2: THE COORDINATE SYSTEM
// ============================================================================
//
// The app uses a PERCENTAGE-BASED coordinate system (0-100) on both axes.
// There are TWO coordinate spaces:
//
//   RAW coordinates:   Stored in JSON files. Represent position within the
//                      PLAYABLE area only (0,0 = top-left of playable zone,
//                      100,100 = bottom-right of playable zone).
//
//   DISPLAY coordinates: Used for on-screen rendering. Represent position
//                        within the FULL image (0,0 = top-left of entire
//                        image, 100,100 = bottom-right of entire image).
//
// The borderOffset defines the non-playable margins. For a map with:
//   borderOffset: { top: 12, bottom: 12, left: 8, right: 8 }
//
// The playable area occupies:
//   X: from 8% to 92% of the image width  (effective width = 84%)
//   Y: from 12% to 88% of the image height (effective height = 76%)
//
// ============================================================================


// ============================================================================
// STEP 3: CONVERSION FORMULAS
// ============================================================================

/**
 * Convert RAW coordinates (stored in JSON) to DISPLAY coordinates (on screen).
 * This is the FORWARD transformation.
 *
 * Formula:
 *   displayX = left + (rawX / 100) * (100 - left - right)
 *   displayY = top  + (rawY / 100) * (100 - top - bottom)
 */
function rawToDisplay(rawX, rawY, borderOffset) {
  if (!borderOffset) return { x: rawX, y: rawY };

  const effectiveWidth  = 100 - borderOffset.left - borderOffset.right;
  const effectiveHeight = 100 - borderOffset.top  - borderOffset.bottom;

  return {
    x: borderOffset.left + (rawX / 100) * effectiveWidth,
    y: borderOffset.top  + (rawY / 100) * effectiveHeight,
  };
}

/**
 * Convert DISPLAY coordinates (on screen) to RAW coordinates (for JSON storage).
 * This is the INVERSE transformation.
 *
 * Formula:
 *   rawX = ((displayX - left) / (100 - left - right)) * 100
 *   rawY = ((displayY - top)  / (100 - top - bottom)) * 100
 */
function displayToRaw(displayX, displayY, borderOffset) {
  if (!borderOffset) return { x: displayX, y: displayY };

  const effectiveWidth  = 100 - borderOffset.left - borderOffset.right;
  const effectiveHeight = 100 - borderOffset.top  - borderOffset.bottom;

  return {
    x: Math.round(((displayX - borderOffset.left) / effectiveWidth)  * 100 * 100) / 100,
    y: Math.round(((displayY - borderOffset.top)  / effectiveHeight) * 100 * 100) / 100,
  };
}


// ============================================================================
// STEP 4: PIXEL-TO-PERCENTAGE CONVERSION
// ============================================================================
//
// When analyzing a map image externally (e.g., in Photoshop, GIMP, or code),
// you start with PIXEL coordinates. Here's how to convert:
//
//   1. Get the image dimensions (width_px, height_px)
//   2. Convert pixel to display percentage:
//        displayX = (pixelX / width_px) * 100
//        displayY = (pixelY / height_px) * 100
//   3. Convert display percentage to raw coordinates using displayToRaw()
//   4. The raw coordinates are what goes into the JSON data files
//

/**
 * Convert pixel coordinates on the source image to RAW JSON coordinates.
 * 
 * @param {number} pixelX - X position in pixels from left edge of image
 * @param {number} pixelY - Y position in pixels from top edge of image
 * @param {number} imageWidth - Total image width in pixels
 * @param {number} imageHeight - Total image height in pixels
 * @param {object} borderOffset - The map's border offset configuration
 * @returns {{ x: number, y: number }} - RAW coordinates for JSON storage
 */
function pixelToRaw(pixelX, pixelY, imageWidth, imageHeight, borderOffset) {
  const displayX = (pixelX / imageWidth) * 100;
  const displayY = (pixelY / imageHeight) * 100;
  return displayToRaw(displayX, displayY, borderOffset);
}

/**
 * Convert RAW JSON coordinates to pixel coordinates on the source image.
 * 
 * @param {number} rawX - X coordinate from JSON (0-100 within playable area)
 * @param {number} rawY - Y coordinate from JSON (0-100 within playable area)
 * @param {number} imageWidth - Total image width in pixels
 * @param {number} imageHeight - Total image height in pixels
 * @param {object} borderOffset - The map's border offset configuration
 * @returns {{ x: number, y: number }} - Pixel coordinates on the image
 */
function rawToPixel(rawX, rawY, imageWidth, imageHeight, borderOffset) {
  const display = rawToDisplay(rawX, rawY, borderOffset);
  return {
    x: Math.round((display.x / 100) * imageWidth),
    y: Math.round((display.y / 100) * imageHeight),
  };
}


// ============================================================================
// STEP 5: ASPECT RATIO & RENDERED SIZE
// ============================================================================
//
// When the app renders a map, it fits the image into the available screen
// space while preserving the aspect ratio. The rendered size determines
// how pixel-level interactions map to percentage coordinates.
//
// Given a container of size (containerW, containerH):
//
//   containerAspect = containerW / containerH
//
//   If containerAspect > imageAspect:
//     // Container is wider than image - height fills, width has margins
//     renderedHeight = containerH
//     renderedWidth  = containerH * imageAspect
//   Else:
//     // Container is taller than image - width fills, height has margins
//     renderedWidth  = containerW
//     renderedHeight = containerW / imageAspect
//
//   offsetX = (containerW - renderedWidth) / 2
//   offsetY = (containerH - renderedHeight) / 2
//
// When converting touch/click coordinates to percentages:
//   percentX = ((touchX - offsetX) / renderedWidth) * 100
//   percentY = ((touchY - offsetY) / renderedHeight) * 100
//
// These are DISPLAY percentages. Apply displayToRaw() to get JSON coordinates.

function calculateRenderedSize(containerWidth, containerHeight, aspectRatio) {
  const containerAspect = containerWidth / containerHeight;
  let width, height;

  if (containerAspect > aspectRatio) {
    height = containerHeight;
    width = height * aspectRatio;
  } else {
    width = containerWidth;
    height = width / aspectRatio;
  }

  return {
    width,
    height,
    offsetX: (containerWidth - width) / 2,
    offsetY: (containerHeight - height) / 2,
  };
}


// ============================================================================
// STEP 6: COMPLETE WORKFLOW FOR EXTERNAL AGENTS
// ============================================================================
//
// To replicate the app's coordinate system from an external environment:
//
// 1. OBTAIN THE MAP IMAGE
//    Get the exact same base map image file used by the app.
//    Files are in: assets/images/{mapId}_base_map.{jpg|png}
//
// 2. GET IMAGE DIMENSIONS
//    Read the pixel dimensions of the image (width_px, height_px).
//
// 3. LOOK UP MAP CONFIGURATION
//    From assetRegistry.ts: get the aspectRatio
//    From {mapId}_data.json: get the borderOffset
//
// 4. IDENTIFY YOUR TARGET POINT
//    In any image editor, find the pixel coordinates of your target point.
//    Example: In the Fate map, the church entrance is at pixel (655, 424)
//             on a 1310x848 image.
//
// 5. CONVERT TO RAW COORDINATES
//    displayX = (655 / 1310) * 100 = 50.0%
//    displayY = (424 / 848)  * 100 = 50.0%
//
//    For Fate (borderOffset: { top: 12, bottom: 12, left: 8, right: 8 }):
//    rawX = ((50.0 - 8) / (100 - 8 - 8)) * 100 = 50.0%
//    rawY = ((50.0 - 12) / (100 - 12 - 12)) * 100 = 50.0%
//
// 6. STORE IN JSON
//    Use the raw coordinates in the map's _data.json file:
//    "coordinates": { "x": 50.0, "y": 50.0 }
//
// 7. VERIFY
//    Run: node scripts/map-coordinate-algorithm.js --percent fate 50 50
//    This will show the display position and pixel position for verification.
//


// ============================================================================
// CLI INTERFACE
// ============================================================================

function printMapInfo(config) {
  console.log(`\n=== ${config.mapName} (${config.mapId}) ===`);
  console.log(`  Aspect Ratio: ${config.aspectRatio} (width/height)`);
  console.log(`  Border Offset: top=${config.borderOffset.top}%, bottom=${config.borderOffset.bottom}%, left=${config.borderOffset.left}%, right=${config.borderOffset.right}%`);
  
  const ew = 100 - config.borderOffset.left - config.borderOffset.right;
  const eh = 100 - config.borderOffset.top - config.borderOffset.bottom;
  console.log(`  Playable Area: ${ew}% width x ${eh}% height`);
  console.log(`  Playable X Range: ${config.borderOffset.left}% to ${100 - config.borderOffset.right}%`);
  console.log(`  Playable Y Range: ${config.borderOffset.top}% to ${100 - config.borderOffset.bottom}%`);

  console.log(`\n  POI Coordinates (raw → display):`);
  config.pointsOfInterest.forEach(poi => {
    const raw = poi.coordinates;
    const disp = rawToDisplay(raw.x, raw.y, config.borderOffset);
    console.log(`    ${poi.id}: raw(${raw.x}, ${raw.y}) → display(${disp.x.toFixed(1)}, ${disp.y.toFixed(1)})`);
  });

  if (config.objectives.domination) {
    console.log(`\n  Domination Objectives:`);
    config.objectives.domination.forEach(obj => {
      const raw = obj.coordinates;
      const disp = rawToDisplay(raw.x, raw.y, config.borderOffset);
      console.log(`    Zone ${obj.zone}: raw(${raw.x}, ${raw.y}) → display(${disp.x.toFixed(1)}, ${disp.y.toFixed(1)})`);
    });
  }

  if (config.objectives.hardpoint) {
    console.log(`\n  Hardpoint Objectives:`);
    config.objectives.hardpoint.forEach(obj => {
      const raw = obj.coordinates;
      const disp = rawToDisplay(raw.x, raw.y, config.borderOffset);
      console.log(`    HP ${obj.number}: raw(${raw.x}, ${raw.y}) → display(${disp.x.toFixed(1)}, ${disp.y.toFixed(1)})`);
    });
  }
}

function getImageDimensions(mapId) {
  const extensions = ['png', 'jpg'];
  for (const ext of extensions) {
    const imgPath = path.join(__dirname, '..', 'assets', 'images', `${mapId}_base_map.${ext}`);
    if (fs.existsSync(imgPath)) {
      const buf = fs.readFileSync(imgPath);
      if (ext === 'png') {
        return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20), path: imgPath };
      } else if (ext === 'jpg') {
        let offset = 2;
        while (offset < buf.length) {
          if (buf[offset] !== 0xFF) break;
          const marker = buf[offset + 1];
          const blockLen = buf.readUInt16BE(offset + 2);
          if (marker >= 0xC0 && marker <= 0xCF && marker !== 0xC4 && marker !== 0xC8) {
            return { width: buf.readUInt16BE(offset + 7), height: buf.readUInt16BE(offset + 5), path: imgPath };
          }
          offset += 2 + blockLen;
        }
      }
    }
  }
  return null;
}

function handlePixelConversion(mapId, pixelX, pixelY) {
  const config = loadMapConfig(mapId);
  const dims = getImageDimensions(mapId);

  console.log(`\n=== Pixel → Raw Coordinate Conversion ===`);
  console.log(`  Map: ${config.mapName}`);
  console.log(`  Border Offset: ${JSON.stringify(config.borderOffset)}`);

  if (dims) {
    console.log(`  Image: ${dims.width}x${dims.height} (auto-detected from ${path.basename(dims.path)})`);
    const raw = pixelToRaw(pixelX, pixelY, dims.width, dims.height, config.borderOffset);
    const display = { x: (pixelX / dims.width) * 100, y: (pixelY / dims.height) * 100 };
    console.log(`\n  Pixel:   (${pixelX}, ${pixelY})`);
    console.log(`  Display: (${display.x.toFixed(2)}%, ${display.y.toFixed(2)}%)`);
    console.log(`  Raw:     (${raw.x}, ${raw.y})  ← use this in JSON`);
  } else {
    console.log(`  WARNING: Could not auto-detect image dimensions.`);
    console.log(`  Supply image dimensions manually or check the image properties.`);
  }
}

function handlePercentConversion(mapId, rawX, rawY) {
  const config = loadMapConfig(mapId);
  const display = rawToDisplay(rawX, rawY, config.borderOffset);
  
  console.log(`\n=== Raw → Display Coordinate Conversion ===`);
  console.log(`  Map: ${config.mapName}`);
  console.log(`  Border Offset: ${JSON.stringify(config.borderOffset)}`);
  console.log(`  Raw (JSON):     (${rawX}, ${rawY})`);
  console.log(`  Display (screen): (${display.x.toFixed(2)}, ${display.y.toFixed(2)})`);
  
  const inverse = displayToRaw(display.x, display.y, config.borderOffset);
  console.log(`  Roundtrip verify: (${inverse.x}, ${inverse.y})`);
}

// ============================================================================
// EXPORTED FUNCTIONS (for use as a module by other scripts/agents)
// ============================================================================
module.exports = {
  loadMapConfig,
  rawToDisplay,
  displayToRaw,
  pixelToRaw,
  rawToPixel,
  calculateRenderedSize,
  getImageDimensions,
};


// ============================================================================
// CLI ENTRY POINT (only runs when executed directly, not when required)
// ============================================================================
if (require.main === module) {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.log('Usage:');
    console.log('  node map-coordinate-algorithm.js <mapId>              Show map info and all POI coordinates');
    console.log('  node map-coordinate-algorithm.js --pixel <mapId> <x> <y>   Convert pixel to raw coordinates');
    console.log('  node map-coordinate-algorithm.js --percent <mapId> <x> <y> Convert raw to display coordinates');
    console.log('  node map-coordinate-algorithm.js --all                     Show all maps');
    console.log('\nAvailable maps: utopia, blackheart, colossus, cortex, odysseus, fate');
    process.exit(0);
  }

  if (args[0] === '--all') {
    ['utopia', 'blackheart', 'colossus', 'cortex', 'odysseus', 'fate'].forEach(mapId => {
      printMapInfo(loadMapConfig(mapId));
    });
  } else if (args[0] === '--pixel' && args.length >= 4) {
    handlePixelConversion(args[1], parseFloat(args[2]), parseFloat(args[3]));
  } else if (args[0] === '--percent' && args.length >= 4) {
    handlePercentConversion(args[1], parseFloat(args[2]), parseFloat(args[3]));
  } else if (args.length === 1) {
    printMapInfo(loadMapConfig(args[0]));
  } else {
    console.error('Invalid arguments. Run without arguments for usage.');
    process.exit(1);
  }
}
